export function answerInterpretation(item, language='en') {
 const index=Number(item.id.slice(1))-1;
 const english=en[index], row=language==='hi'?hi[index]:english.slice(1);
 if(!row||!['support','focus','varies'].includes(item.category))throw new Error('A complete question response is needed for an insight.');
 const offset=item.category==='support'?0:2;
 return {
  icon:english[0],
  title:item.category==='varies'?itemReflections[index][language==='hi'?1:0]:row[offset],
  meaning:item.category==='varies'?row[4]:row[offset+1],
  practice:row[5]
 };
}
